class InMemoryStockRepository:
    def __init__(self) -> None:
        self._stock: dict[str, int] = {}
        self._lock = asyncio.Lock()

async def get_many(self, sku_ids: Iterable[str]) -> Mapping[str, int]:
    async with self._lock:
        return {sku_id: self._stock[sku_id] for sku_id in sku_ids if sku_id in self._stock}

